import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Globe } from 'lucide-react';
import React, { useEffect } from 'react';
import { router } from '@inertiajs/react';

// 定义支持的语言
const languages = [
    { code: 'chinese_simplified', label: '简体中文' },
    { code: 'chinese_traditional', label: '繁體中文' },
    { code: 'english', label: 'English' },
    { code: 'korean', label: '한국어' },
    { code: 'japanese', label: '日本語' },
    { code: 'french', label: 'Français' },
    { code: 'german', label: 'Deutsch' },
    { code: 'spanish', label: 'Español' },
    { code: 'russian', label: 'Русский' },
    { code: 'arabic', label: 'العربية' },
    { code: 'portuguese', label: 'Português' },
    { code: 'italian', label: 'Italiano' },
    { code: 'dutch', label: 'Nederlands' },
    { code: 'thai', label: 'ไทย' },
    { code: 'vietnamese', label: 'Tiếng Việt' },
    { code: 'indonesian', label: 'Bahasa Indonesia' },
    { code: 'hindi', label: 'हिन्दी' },
    { code: 'malay', label: 'Bahasa Melayu' },
];

export function LanguageSelector() {
    const handleLanguageChange = (langCode: string) => {
        if ((window as any).translate) {
            (window as any).translate.changeLanguage(langCode);
        } else {
            console.warn('Translate.js is not loaded');
        }
    };

    // 监听 Inertia 页面导航，重新应用翻译
    useEffect(() => {
        const removeListener = router.on('finish', () => {
             // 稍微延迟以确保 DOM 更新完成
            setTimeout(() => {
                if ((window as any).translate) {
                    (window as any).translate.execute();
                }
            }, 100);
        });

        // 组件首次挂载时也尝试执行一次（针对硬刷新后的情况）
        if ((window as any).translate) {
            // 检查是否已有保存的语言设置，如果有则应用
             // translate.js 通常会自动处理，但为了保险起见可以手动触发
            (window as any).translate.execute();
        }

        return () => {
            removeListener();
        };
    }, []);

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon" className="h-9 w-9 rounded-full text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800">
                    <Globe className="h-4 w-4" />
                    <span className="sr-only">Switch Language</span>
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="max-h-[300px] overflow-y-auto">
                {languages.map((lang) => (
                    <DropdownMenuItem
                        key={lang.code}
                        onClick={() => handleLanguageChange(lang.code)}
                        className="cursor-pointer"
                    >
                        {lang.label}
                    </DropdownMenuItem>
                ))}
            </DropdownMenuContent>
        </DropdownMenu>
    );
}
